168	  function canonicalDigits(raw) {
169	    if (!/^\d+$/.test(raw)) return null;
170	    var digits = raw.replace(/^0+/, "");
171	    if (digits === "") return null; // 全是 0：容量为零，不接受
172	    return digits;
173	  }
174	
175	  // buildVenueRequestBody 直接拼接 JSON 文本，让容量以输入的十进制数字原文
176	  // 发送：不能用 JSON.stringify({capacity: 数字})，大整数在转成 Number 时
177	  // 已经被舍入，stringify 只会写回错误的值。名称、时区是字符串，交给
178	  // JSON.stringify 转义；传输报文中 capacity 仍是 JSON 数字。
179	  function buildVenueRequestBody(name, capacityDigits, timezone, hours) {
180	    return "{" +
181	      '"name":' + JSON.stringify(name) +
182	      ',"capacity":' + capacityDigits +
183	      ',"timezone":' + JSON.stringify(timezone) +
184	      ',"weeklyHours":' + JSON.stringify(hours) +
185	      "}";
186	  }
187	
188	  // parseVenuesJSON 解析场地列表，但保留 capacity 数字的十进制原文：
189	  // JSON.parse 会把数字存成 float64，超过 2^53 的容量会被舍入成相邻整数。
190	  // 这里逐字符扫描 JSON（正确处理字符串内的转义引号），仅当 "capacity"
191	  // 作为对象键出现时，把其后数字的原文包成字符串，页面拿到的就是服务端
192	  // 逐位发出的完整十进制数字（服务端只输出普通整数，不会出现科学计数法）。
193	  // 名称等其它字段一律原样复制，绝不改写；线上传输的 JSON 中 capacity
194	  // 仍是数字，接口格式不变。
195	  function parseVenuesJSON(text) {
196	    var out = "", i = 0, n = text.length;
197	    while (i < n) {
198	      if (text[i] !== '"') {
199	        out += text[i];
200	        i++;
201	        continue;
202	      }
203	      // 读取完整字符串，跳过转义字符，使名称中出现的 \"capacity\":1
204	      // 之类文本不会被误认为对象键。
205	      var tokenStart = i, j = i + 1;
206	      while (j < n) {
207	        if (text[j] === "\\") { j += 2; continue; }
208	        if (text[j] === '"') { j++; break; }
209	        j++;
210	      }
211	      var token = text.slice(tokenStart, j);
212	      // 对象键后面（允许空白）必然是 ':'；字符串值后面只能是 ',' 或 '}'。
213	      var k = j;
214	      while (k < n && /\s/.test(text[k])) k++;
215	      if (text[k] !== ":" || JSON.parse(token) !== "capacity") {
216	        out += token;
217	        i = j;
218	        continue;
219	      }
220	      // 复制到 ':' 之后（含中间空白），再把数字原文引用为字符串。
221	      out += token + text.slice(j, k + 1);
222	      var p = k + 1;
223	      while (p < n && /\s/.test(text[p])) { out += text[p]; p++; }
224	      var numStart = p;
225	      while (p < n && /[-+0-9eE.]/.test(text[p])) p++;
226	      out += JSON.stringify(text.slice(numStart, p));
227	      i = p;
228	    }
229	    return JSON.parse(out);
230	  }
