82	// load 读取并解析全部记录。读不到、JSON 损坏、结构异常或任一场地的
83	// 开放时段不合法都返回错误，调用方必须按 500 处理，绝不能把错误数据
84	// 当作空列表覆盖，也不能跳过异常场地只返回剩余记录。
85	func (s *store) load() ([]Venue, error) {
86		raw, err := os.ReadFile(s.path)
87		if err != nil {
88			return nil, err
89		}
90		var venues []Venue
91		if err := json.Unmarshal(raw, &venues); err != nil {
92			return nil, fmt.Errorf("venues data is corrupted: %w", err)
93		}
94		if venues == nil {
95			venues = []Venue{}
96		}
97		for i := range venues {
98			// 兼容旧数据：字段缺省或为 null 仍按空数组（暂未开放）读取。
99			if venues[i].WeeklyHours == nil {
100				venues[i].WeeklyHours = []WeeklyHour{}
101			}
102			// 已保存数据同样必须满足新增时的全部时段规则；任一非法即视为损坏。
103			if err := validateHours(venues[i].WeeklyHours); err != nil {
104				return nil, fmt.Errorf("venues data is corrupted: venue %q has invalid weekly hours: %w", venues[i].ID, err)
105			}
106		}
107		return venues, nil
108	}
