144	// create 校验请求内容，通过后写入新记录并返回保存后的场地。
145	// 校验失败时返回 apiError（400），不会写入任何内容。
146	func (s *store) create(payload map[string]any) (Venue, error) {
147		s.mu.Lock()
148		defer s.mu.Unlock()
149	
150		venues, err := s.load()
151		if err != nil {
152			return Venue{}, err
153		}
154	
155		venue, err := buildVenue(payload)
156		if err != nil {
157			return Venue{}, err
158		}
