237	// parseJSONInteger 按 JSON 数字的准确十进制文本判断它是否为整数，并返回其
238	// 精确值。value 必须来自开启了 UseNumber 的 JSON 解码（即 json.Number），
239	// 这样即使是 9007199254740993 这样超过 float64 安全整数范围、或
240	// 120.00000000000000001 这样带极小小数的数字，也不会在转换中被悄悄舍入。
241	//
242	// 返回值含义：
243	//   - isInt=false：不是 JSON 整数（根本不是数字，或带有非零小数部分）；
244	//   - isInt=true、inRange=true：z 是精确的整数值，且能放进 int64；
245	//   - isInt=true、inRange=false：确实是整数，但超出 int64 可表示范围，
246	//     此时 z 为 nil，sign 仍标明它是正数还是负数。
247	//
248	// 120、120.0、1.2e2 都得到整数 120；120.00000000000000001 和 1e-1 则带
249	// 小数部分，判定为非整数。
250	func parseJSONInteger(value any) (z *big.Int, sign int, isInt bool, inRange bool) {
251		switch number := value.(type) {
252		case json.Number:
253			return parseIntegerText(string(number))
254		case float64:
255			// 兼容直接在进程内构造 map（如测试）的调用方。HTTP 入口已启用
256			// UseNumber，不会走到这里；此处能看到的只有调用方手中的 float64，
257			// 按其当前值做精确的整数判断即可。
258			if math.IsNaN(number) || math.IsInf(number, 0) || number != math.Trunc(number) {
259				return nil, 0, false, false
260			}
261			sig := 1
262			switch {
263			case number < 0:
264				sig = -1
265			case number == 0:
266				sig = 0
267			}
268			// 用严格的 2^63 边界比较，避免 float64(math.MaxInt64) 进位到 2^63
269			// 后再转 int64 发生溢出回绕。
270			if number < -9223372036854775808.0 || number >= 9223372036854775808.0 {
271				return nil, sig, true, false
272			}
273			n := int64(number)
274			return big.NewInt(n), sig, true, true
275		default:
276			return nil, 0, false, false
277		}
278	}
