280	// parseIntegerText 按 JSON 数字的原始十进制文本做精确解析，逻辑见
281	// parseJSONInteger 的说明。
282	func parseIntegerText(text string) (z *big.Int, sign int, isInt bool, inRange bool) {
283		mant, exp, ok := decimalNumber(text)
284		if !ok {
285			return nil, 0, false, false
286		}
287		if mant.Sign() == 0 {
288			// 0、0.0、0e10 等都精确等于整数 0。
289			return big.NewInt(0), 0, true, true
290		}
291		// 极大/极小指数下无需真的构造巨大整数：非零尾数乘 10^exp 必然超出
292		// int64；非零数除以足够大的 10 的幂必然留下小数部分。
293		switch {
294		case exp > 100000:
295			return nil, mant.Sign(), true, false
296		case exp < -100000:
297			return nil, mant.Sign(), false, false
298		}
299		z = new(big.Int).Set(mant)
300		if exp >= 0 {
301			z.Mul(z, new(big.Int).Exp(big.NewInt(10), big.NewInt(exp), nil))
302		} else {
303			divisor := new(big.Int).Exp(big.NewInt(10), big.NewInt(-exp), nil)
304			abs := new(big.Int).Set(z)
305			if abs.Sign() < 0 {
306				abs.Neg(abs)
307			}
308			// 不能被 10^(-exp) 整除，说明小数点后存在非零数字，不是整数。
309			if new(big.Int).Mod(abs, divisor).Sign() != 0 {
310				return nil, mant.Sign(), false, false
311			}
312			z.Quo(z, divisor)
313		}
314		if !z.IsInt64() {
315			return nil, z.Sign(), true, false
316		}
317		return z, z.Sign(), true, true
318	}
