320	// decimalNumber 把 JSON 数字文本拆成带符号的整数尾数 m 与十进制指数 e，
321	// 使 原值 == m * 10^e。输入来自合法 JSON 解码，不接受 Infinity/NaN。
322	func decimalNumber(text string) (m *big.Int, e int64, ok bool) {
323		s := text
324		neg := false
325		if len(s) > 0 && (s[0] == '+' || s[0] == '-') {
326			neg = s[0] == '-'
327			s = s[1:]
328		}
329		if s == "" {
330			return nil, 0, false
331		}
332		rest, expText, hasExp := s, "", false
333		if i := strings.IndexAny(s, "eE"); i >= 0 {
334			rest, expText, hasExp = s[:i], s[i+1:], true
335		}
336		body := rest
337		if i := strings.IndexByte(rest, '.'); i >= 0 {
338			whole, frac := rest[:i], rest[i+1:]
339			if frac == "" {
340				return nil, 0, false // 如 "1."，不是合法 JSON 数字
341			}
342			body = whole + frac
343			e = -int64(len(frac))
344		}
345		if body == "" || !isDigits(body) {
346			return nil, 0, false
347		}
348		if hasExp {
349			exp, err := strconv.ParseInt(expText, 10, 64)
350			if err != nil {
351				return nil, 0, false
352			}
353			e += exp
354		}
355		m, ok = new(big.Int).SetString(body, 10)
356		if !ok {
357			return nil, 0, false
358		}
359		if neg {
360			m.Neg(m)
361		}
362		return m, e, true
363	}
364	
365	func isDigits(s string) bool {
366		if s == "" {
367			return false
368		}
369		for i := 0; i < len(s); i++ {
370			if s[i] < '0' || s[i] > '9' {
371				return false
372			}
373		}
374		return true
375	}
376	
377	// requirePositiveInt 校验表示人数的容量字段：必须是 JSON 数字、按准确数值
378	// 判断为正整数，且落在支持的整数范围内。任何非正整数（零、负数以及带小数
379	// 部分的数字）都返回“必须是正整数”；是整数但超出范围则返回“超出支持范围”，
380	// 绝不截断或舍入成相邻整数保存。
381	func requirePositiveInt(payload map[string]any, field string) (int, error) {
382		value, ok := payload[field]
383		if !ok || value == nil {
384			return 0, missingOrWrong(field, "正整数")
385		}
386		z, sign, isInt, inRange := parseJSONInteger(value)
387		if !isInt || sign <= 0 {
388			return 0, missingOrWrong(field, "正整数")
389		}
390		if !inRange || z.Int64() > maxVenueCapacity {
391			return 0, badRequest("%s 超出支持范围：容量必须是 1 到 %d 的整数", field, maxVenueCapacity)
392		}
393		return int(z.Int64()), nil
394	}
395	
396	// requireWeekday 用与容量相同的精确文本解析星期字段，保证只接受 1 到 7 的
397	// 整数（1.5 这类带小数的值不会被舍入后接受）。
398	func requireWeekday(value any, i int) (int, error) {
399		z, _, isInt, inRange := parseJSONInteger(value)
400		if !isInt {
401			return 0, badRequest("weeklyHours[%d].weekday 类型错误：应为 1 到 7 的整数", i)
402		}
403		if !inRange || z.Int64() < 1 || z.Int64() > 7 {
404			return 0, badRequest("weeklyHours[%d].weekday 必须为 1 到 7（周一至周日）", i)
405		}
406		return int(z.Int64()), nil
407	}
408	
409	func parseWeeklyHours(raw any) ([]WeeklyHour, error) {
410		if raw == nil {
411			return nil, badRequest("weeklyHours 类型错误：应为数组")
412		}
413		items, ok := raw.([]any)
414		if !ok {
415			return nil, badRequest("weeklyHours 类型错误：应为数组")
416		}
417		hours := make([]WeeklyHour, 0, len(items))
418		for i, item := range items {
419			obj, ok := item.(map[string]any)
420			if !ok || obj == nil {
421				return nil, badRequest("weeklyHours[%d] 类型错误：应为对象", i)
422			}
423			rawWeekday, ok := obj["weekday"]
424			if !ok || rawWeekday == nil {
425				return nil, badRequest("weeklyHours[%d].weekday 类型错误：应为 1 到 7 的整数", i)
426			}
427			weekday, err := requireWeekday(rawWeekday, i)
428			if err != nil {
429				return nil, err
430			}
431			start, err := hourField(obj, i, "start")
432			if err != nil {
433				return nil, err
434			}
435			end, err := hourField(obj, i, "end")
436			if err != nil {
437				return nil, err
438			}
439			hours = append(hours, WeeklyHour{Weekday: weekday, Start: start, End: end})
440		}
441		return hours, nil
442	}
443	
444	func hourField(obj map[string]any, i int, field string) (string, error) {
445		value, ok := obj[field]
446		if !ok || value == nil {
447			return "", badRequest("weeklyHours[%d].%s 类型错误：应为 HH:mm 时间", i, field)
448		}
449		str, ok := value.(string)
450		if !ok || !validHHMM(str) {
451			return "", badRequest("weeklyHours[%d].%s 时间无效，必须为 00:00 至 23:59 的 HH:mm 格式", i, field)
452		}
453		return str, nil
454	}
455	
456	// validHHMM 严格校验 HH:mm：两位小时、冒号、两位分钟，范围 00:00–23:59。
457	func validHHMM(value string) bool {
458		if len(value) != 5 || value[2] != ':' {
459			return false
460		}
461		for i, c := range value {
462			if i == 2 {
463				continue
464			}
465			if c < '0' || c > '9' {
466				return false
467			}
468		}
469		hour := int(value[0]-'0')*10 + int(value[1]-'0')
470		minute := int(value[3]-'0')*10 + int(value[4]-'0')
471		return hour <= 23 && minute <= 59
472	}
473	
474	func minutes(value string) int {
475		return int(value[0]-'0')*600 + int(value[1]-'0')*60 +
476			int(value[3]-'0')*10 + int(value[4]-'0')
477	}
478	
479	// interval 是展开到周时间轴上的一段开放时间，单位为分钟。
480	// 周一 00:00 为起点 0。
481	type interval struct {
482		start int
483		end   int
484		label string
485	}
486	
487	// validateHours 按开放时段的业务规则检查一段已解析的时段数据。
488	// 规则同时用于新增请求（400 校验）和已保存数据（损坏时按 500 处理）：
489	// 星期为 1–7（周一至周日），时间为严格 HH:mm（00:00–23:59），
490	// 起止时间不能相同；结束早于开始表示次日结束。重叠判断覆盖跨午夜
491	// 延续到次日的部分，也包含周日延续到下周一的部分；部分重叠、完全
492	// 包含和重复时段都不合法，下一段恰好在前一段结束时开始合法。
493	// 时段的填写顺序不影响结果。
494	//
495	// 返回的是普通错误而非 apiError：读取已保存数据命中时按数据损坏（500）
496	// 处理；新增流程由 buildVenue 包装成面向客户端的 400 错误。
497	func validateHours(hours []WeeklyHour) error {
498		intervals := make([]interval, 0, len(hours)*2)
499		for _, h := range hours {
500			if h.Weekday < 1 || h.Weekday > 7 {
501				return fmt.Errorf("开放时段无效：星期 %d 不在 1 到 7（周一至周日）范围内", h.Weekday)
502			}
503			if !validHHMM(h.Start) || !validHHMM(h.End) {
504				return fmt.Errorf("开放时段无效：%s 的时间 %s-%s 不是合法的 HH:mm", weekdayName(h.Weekday), h.Start, h.End)
505			}
506			startMin := minutes(h.Start)
507			endMin := minutes(h.End)
508			label := fmt.Sprintf("%s %s-%s", weekdayName(h.Weekday), h.Start, h.End)
509			if startMin == endMin {
510				return fmt.Errorf("开放时段无效：%s 的结束时间与开始时间相同", label)
511			}
512			start := (h.Weekday-1)*1440 + startMin
513			end := (h.Weekday-1)*1440 + endMin
514			if endMin < startMin {
515				end += 1440 // 跨午夜，次日结束
516			}
517			intervals = append(intervals, interval{start: start, end: end, label: label})
518		}
519		// 复制到下一周，用于检测周日跨午夜与下周一时段相交。
520		base := make([]interval, len(intervals))
521		copy(base, intervals)
522		for _, iv := range base {
523			intervals = append(intervals, interval{
524				start: iv.start + 7*1440,
525				end:   iv.end + 7*1440,
526				label: iv.label,
527			})
528		}
529		sort.Slice(intervals, func(i, j int) bool {
530			if intervals[i].start != intervals[j].start {
531				return intervals[i].start < intervals[j].start
532			}
533			return intervals[i].end < intervals[j].end
534		})
535		for i := 1; i < len(intervals); i++ {
536			if intervals[i].start < intervals[i-1].end {
537				return fmt.Errorf("开放时段存在相交：%s 与其他时段重叠", intervals[i].label)
538			}
539		}
540		return nil
541	}
542	
543	func weekdayName(weekday int) string {
544		return [...]string{"", "周一", "周二", "周三", "周四", "周五", "周六", "周日"}[weekday]
545	}
546	
547	// newID 生成非空、概率上唯一的记录标识。
548	func newID() string {
549		b := make([]byte, 16)
550		if _, err := rand.Read(b); err != nil {
551			// crypto/rand 失败极不寻常；退化为纳秒时间戳，仍保证非空且基本唯一。
552			return fmt.Sprintf("v-%d", time.Now().UnixNano())
553		}
554		return hex.EncodeToString(b)
555	}
556	
557	func idTaken(venues []Venue, id string) bool {
558		for _, v := range venues {
559			if v.ID == id {
560				return true
561			}
562		}
563		return false
564	}
565

