275	      name: card.querySelector("h3") ? card.querySelector("h3").textContent : "",
276	      text: card.textContent
277	    };
278	  });
279	  return {
280	    listText: document.getElementById("venue-list").textContent,
281	    error: errorBox.style.display === "none" ? null : errorBox.textContent,
282	    form: {
283	      name: document.getElementById("name").value,
284	      capacity: document.getElementById("capacity").value,
