350	    const submit = () => cdp.eval(`(${PAGE_SUBMIT})()`);
351	    const findCard = (cards, name) => cards.find((c) => c.name === name) || null;
352	    const capacityOnCard = (card) => {
353	      const m = card.text.match(/容量：(\S+)\s*人/);
