370	    // 从 JSON 文本里取出 capacity 的原始写法（不解析成 Number）。
371	    const rawCapacityToken = (raw) => {
372	      const m = raw.match(/"capacity"\s*:\s*([^,}\s]+)/);
373	      return m ? m[1] : null;
374	    };
