387	        const token = raw ? rawCapacityToken(raw) : null;
388	        check(S, "请求 capacity 逐位等于 9007199254740993", token === exact,
389	          `token=${token} body=${raw}`);
390	        check(S, "请求 capacity 是未加引号的 JSON 数字", token !== null && token[0] !== '"',
391	          `token=${token}`);
392	        check(S, "请求未被舍入成相邻整数 9007199254740992", raw.indexOf(neighbor) === -1, raw);
393	        check(S, "服务端返回 201", post.status === 201, `status=${post.status}`);
394	
395	        let s0 = await state();
